head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf55000";

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — message, newYn

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_if_14", fn: function(){ return ((((dma_pageContext.get("message") ?? "")) && typeof ((dma_pageContext.get("message") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("message") ?? "")).getRowCount() : ((((dma_pageContext.get("message") ?? "")) == null) ? 0 : (((dma_pageContext.get("message") ?? "")).length || 0))) > 0); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("message") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $("input[name=isur_cd]").focus().select();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf55000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_searchForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf55000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_isurCd_onkeypress
 * @description ipt_isurCd onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_isurCd_onkeypress = async function(e){
    try {
        const ev = e;
        const event = ev;
        return await scwin.enterEvent(event);

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf55000.ipt_isurCd_onkeypress' }); }
};

/**
 * @method
 * @name ipt_isurCd_onpaste
 * @description ipt_isurCd onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_isurCd_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf55000.ipt_isurCd_onpaste' }); }
};

/**
 * @method
 * @name btn_searchMember_onclick
 * @description btn_searchMember 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchMember_onclick = async function(e){
    try {
        await scwin.searchMember()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf55000.btn_searchMember_onclick' }); }
};

/**
 * @method
 * @name btn_confirm_onclick
 * @description btn_confirm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_confirm_onclick = async function(e){
    try {
        await scwin.confirm((String(((dma_pageContext.get("newYn") ?? "")) == null ? '' : ((dma_pageContext.get("newYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("newYn") ?? "")) == null ? '' : ((dma_pageContext.get("newYn") ?? "")))))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf55000.btn_confirm_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchMember
 * @description search Member 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchMember = async function () {
    const sbmOptions = {
        id: "tx_fn_searchMember",
        method: "post",
        action: "/register/register.do?method=searchMember",
        ref: "dma_searchMemberReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_confirm
 * @description confirm 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_confirm",
        method: "post",
        action: "/register/register.do?method=registerMemberView",
        ref: "dma_confirmReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchMember
 * @description search Member 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchMember = async function () {
    const vIsurCd = $c.util.getComponent('ipt_isurCd').getValue().replace(/ /gi, "");
    if ($c.str.getByteLength(vIsurCd) === 0) {
        await $c.win.alert("발행기관코드를 입력하십시오.");
        $c.util.getComponent("ipt_isurCd").setValue("");
        $c.util.getComponent("ipt_isurCd").focus();
        return false;
    } else {
        if (vIsurCd.substring(0, 1) === "#") {
            await $c.win.alert("임시발행기관코드는 신청할 수 없습니다.");
            $c.util.getComponent("ipt_isurCd").setValue("");
            $c.util.getComponent("ipt_isurCd").focus();
            return false;
        } else {
            if (vIsurCd.length < 5) {
                await $c.win.alert("발행기관코드 5자리를 입력하십시오.");
                $c.util.getComponent("ipt_isurCd").setValue("");
                $c.util.getComponent("ipt_isurCd").focus();
                return false;
            } else {
                await scwin.tx_fn_searchMember();
            }
        }
    }
};

/**
 * @method
 * @name enterEvent
 * @description enter Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterEvent = async function (e) {
    if (e.keyCode === 13) {
        await scwin.searchMember();
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @param {String} newYn newYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function (newYn) {
    $c.win.closePopup();
    if (newYn !== "N") {
        const width = 1260;
        const height = 900;
        const mtWidth = document.body.clientWidth;
        const mtHeight = document.body.clientHeight;
        const scX = 0;
        const scY = 0;
        const popX = scX + (mtWidth - width) / 2;
        const popY = scY + (mtHeight - height) / 2;
        let _previewWindow;
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/register/register.do?method=registerMemberView", unresolved: "nav:" + "/register/register.do?method=registerMemberView" }; })();
        scwin.form_searchForm.action = "/register/register.do?method=registerMemberView";
        scwin.form_searchForm.target = "popRegisterMember";
    }
};
